function(container, apiUrl, tables) {
  const tableIndex = 0;
  let currentRuleData = {};
  let extractedBeforeData = [];
  let extractedAfterData = [];
  let scheduleList = [];

  // Initialize form with default values
  function initializeForm() {
    container.querySelector('[name="facility"]').value = '';
    container.querySelector('[name="timeslot"]').value = '';
    container.querySelector('[name="usertype"]').value = '';
    container.querySelector('[name="price"]').value = '';
    container.querySelector('[name="cancelDays"]').value = '7';
    container.querySelector('[name="refundRate"]').value = '100';
    container.querySelector('[name="fee"]').value = '0';
    container.querySelector('[name="refundMethod"]').value = '';
    container.querySelector('[name="changeDays"]').value = '14';
    container.querySelector('[name="changeLimit"]').value = '3';
    container.querySelector('[name="changeFee"]').value = '0';
    container.querySelector('[name="approvalRequired"]').value = '';
  }

  // Update change summary
  function updateChangeSummary() {
    const facility = container.querySelector('[name="facility"]').value || '未指定';
    const price = container.querySelector('[name="price"]').value || '0';
    const cancelDays = container.querySelector('[name="cancelDays"]').value || '7';
    const refundRate = container.querySelector('[name="refundRate"]').value || '100';

    container.querySelector('#change-before-summary').textContent = '現在のルール（詳細は別途確認）';
    container.querySelector('#change-after-summary').textContent = `${facility} / ¥${price}/時間 / キャンセル期限${cancelDays}日前 / 返金率${refundRate}%`;
  }

  // Extract affected reservations (before rule)
  container.querySelector('[data-testid="extract-before-button"]').addEventListener('click', async () => {
    try {
      const rows = await window.aivicApi.list(tableIndex);
      extractedBeforeData = rows || [];

      container.querySelector('#impact-before-count').textContent = extractedBeforeData.length;
      container.querySelector('#validation-result').innerHTML = `
        <div style="padding: 12px; background: var(--bg-main); border-radius: var(--radius-control); border-left: 3px solid #a67c52;">
          <div style="font-size: 12px; color: var(--text); margin-bottom: 8px;"><strong>変更前ルール適用対象</strong></div>
          <div style="font-size: 12px; color: var(--text-muted);">
            抽出件数: <strong style="color: var(--text);">${extractedBeforeData.length}件</strong><br/>
            施設別: 体育館 ${extractedBeforeData.filter(r => r.facility === 'gym').length}件 / プール ${extractedBeforeData.filter(r => r.facility === 'pool').length}件
          </div>
        </div>
      `;
    } catch (err) {
      console.error('Error extracting before data:', err);
    }
  });

  // Extract affected reservations (after rule)
  container.querySelector('[data-testid="extract-after-button"]').addEventListener('click', async () => {
    try {
      const rows = await window.aivicApi.list(tableIndex);
      extractedAfterData = rows || [];

      container.querySelector('#impact-after-count').textContent = extractedAfterData.length;

      const beforeCount = parseInt(container.querySelector('#impact-before-count').textContent) || 0;
      const afterCount = extractedAfterData.length;
      const diff = afterCount - beforeCount;

      container.querySelector('#impact-amount-diff').textContent = `${diff > 0 ? '+' : ''}${diff}件`;

      container.querySelector('#validation-result').innerHTML = `
        <div style="padding: 12px; background: var(--bg-main); border-radius: var(--radius-control); border-left: 3px solid #3d7e4a;">
          <div style="font-size: 12px; color: var(--text); margin-bottom: 8px;"><strong>変更後ルール適用対象</strong></div>
          <div style="font-size: 12px; color: var(--text-muted);">
            抽出件数: <strong style="color: var(--text);">${extractedAfterData.length}件</strong><br/>
            差分: <strong style="color: var(--text);">${diff > 0 ? '+' : ''}${diff}件</strong>
          </div>
        </div>
      `;
    } catch (err) {
      console.error('Error extracting after data:', err);
    }
  });

  // Add schedule row
  container.querySelector('[data-testid="add-schedule-button"]').addEventListener('click', () => {
    const startDt = container.querySelector('[name="applyStartDt"]').value;
    const endDt = container.querySelector('[name="applyEndDt"]').value;
    const group = container.querySelector('[name="applyGroup"]').value;

    if (!startDt || !endDt || !group) {
      alert('適用開始日時、終了日時、対象グループを指定してください');
      return;
    }

    const schedule = { startDt, endDt, group, id: Date.now() };
    scheduleList.push(schedule);
    renderScheduleTable();
  });

  // Render schedule table
  function renderScheduleTable() {
    const tbody = container.querySelector('#schedule-tbody');
    if (scheduleList.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted);">スケジュールが登録されていません</td></tr>';
      return;
    }

    tbody.innerHTML = scheduleList.map(s => `
      <tr style="border-bottom: 1px solid var(--border);">
        <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text); font-size: 12px;">${new Date(s.startDt).toLocaleString('ja-JP')}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text); font-size: 12px;">${new Date(s.endDt).toLocaleString('ja-JP')}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text); font-size: 12px;">${s.group}</td>
        <td style="padding: 8px; text-align: center;">
          <button class="delete-schedule-btn" data-id="${s.id}" style="background: none; border: none; color: #8b4545; cursor: pointer; font-size: 12px;">削除</button>
        </td>
      </tr>
    `).join('');

    container.querySelectorAll('.delete-schedule-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const id = parseInt(e.target.dataset.id);
        scheduleList = scheduleList.filter(s => s.id !== id);
        renderScheduleTable();
      });
    });
  }

  // Save rule
  container.querySelector('[data-testid="save-button"]').addEventListener('click', () => {
    const facility = container.querySelector('[name="facility"]').value;
    const price = container.querySelector('[name="price"]').value;

    if (!facility || !price) {
      alert('施設と料金は必須です');
      return;
    }

    const impactCount = parseInt(container.querySelector('#impact-after-count').textContent) || 0;
    container.querySelector('#confirm-impact-count').textContent = impactCount;
    container.querySelector('#confirm-dialog-overlay').style.display = 'flex';
  });

  // Confirm execution
  container.querySelector('[data-testid="confirm-execute-button"]').addEventListener('click', async () => {
    try {
      const ruleData = {
        facility: container.querySelector('[name="facility"]').value,
        timeslot: container.querySelector('[name="timeslot"]').value,
        usertype: container.querySelector('[name="usertype"]').value,
        price: container.querySelector('[name="price"]').value,
        cancelDays: container.querySelector('[name="cancelDays"]').value,
        refundRate: container.querySelector('[name="refundRate"]').value,
        fee: container.querySelector('[name="fee"]').value,
        refundMethod: container.querySelector('[name="refundMethod"]').value,
        changeDays: container.querySelector('[name="changeDays"]').value,
        changeLimit: container.querySelector('[name="changeLimit"]').value,
        changeFee: container.querySelector('[name="changeFee"]').value,
        approvalRequired: container.querySelector('[name="approvalRequired"]').value,
        applyStartDt: container.querySelector('[name="applyStartDt"]').value,
        applyEndDt: container.querySelector('[name="applyEndDt"]').value,
        schedules: scheduleList
      };

      const result = await window.aivicApi.save(tableIndex, ruleData);
      if (result) {
        alert('ルール変更が確定・実行されました');
        container.querySelector('#confirm-dialog-overlay').style.display = 'none';
        initializeForm();
        renderScheduleTable();
      }
    } catch (err) {
      console.error('Error saving rule:', err);
    }
  });

  // Close confirmation dialog
  container.querySelector('[data-testid="confirm-cancel-button"]').addEventListener('click', () => {
    container.querySelector('#confirm-dialog-overlay').style.display = 'none';
  });

  container.querySelector('[data-testid="cancel-button"]').addEventListener('click', () => {
    initializeForm();
    scheduleList = [];
    renderScheduleTable();
  });

  // Update summary on input change
  container.querySelectorAll('input, select').forEach(el => {
    el.addEventListener('change', updateChangeSummary);
  });

  // Close dialog on overlay click
  container.querySelector('#confirm-dialog-overlay').addEventListener('click', (e) => {
    if (e.target === container.querySelector('#confirm-dialog-overlay')) {
      container.querySelector('#confirm-dialog-overlay').style.display = 'none';
    }
  });

  // Keyboard shortcut: Esc to close dialog
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      container.querySelector('#confirm-dialog-overlay').style.display = 'none';
    }
  });

  initializeForm();
  renderScheduleTable();
}
